-- ----------------------------
-- Table structure for payrolls
-- ----------------------------
DROP TABLE IF EXISTS `payrolls`;
CREATE TABLE `payrolls`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `employee_id` bigint UNSIGNED NOT NULL,
  `period` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `base_salary` decimal(15, 2) NOT NULL,
  `attendance_days` int NULL DEFAULT NULL,
  `paid_leave_days` int NOT NULL DEFAULT 0,
  `absent_days` int NULL DEFAULT NULL,
  `allowance` decimal(15, 2) NOT NULL,
  `bonus` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `overtime_pay` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `uang_makan_lembur` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `uang_makan_harian` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `other_additions` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `late_penalty` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `late_penalty_percent` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `absent_penalty` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `cash_advance_deduction` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `bpjs_deduction` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `bpjs_kesehatan_deduction` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `bpjs_kesehatan_company` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `bpjs_ketenagakerjaan_deduction` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `bpjs_ketenagakerjaan_company` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `iuran_bulanan_deduction` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `tax_amount` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `other_deductions` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `total_deductions` decimal(15, 2) NOT NULL,
  `net_salary` decimal(15, 2) NOT NULL,
  `status` enum('draft','approved','paid','cancelled') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'draft',
  `approved_by` bigint UNSIGNED NULL DEFAULT NULL,
  `approval_date` datetime NULL DEFAULT NULL,
  `payment_date` date NULL DEFAULT NULL,
  `payment_method` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `payrolls_employee_id_foreign`(`employee_id` ASC) USING BTREE,
  INDEX `payrolls_approved_by_foreign`(`approved_by` ASC) USING BTREE,
  CONSTRAINT `payrolls_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `payrolls_employee_id_foreign` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 1827 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

